1	//! Owned live primary-plane output. No implicit modeset occurs on Drop.
2	use super::{
3	    SeatDevice,
4	    restore::RestoreState,
5	    target_test::{self, Target},
6	};
7	use crate::{
8	    Ticket,
9	    frames::{self, FramePool, FrameQueue, IdleProof, OutputKey, SubmitError, SubmitOutcome},
10	    output::{Assignment, Format},
11	};
12	use serde::Serialize;
13	use smithay::{
14	    backend::{
15	        allocator::gbm::GbmDevice,
16	        drm::{DrmDevice, DrmDeviceFd},
17	        renderer::{Renderer, gles::GlesRenderer},
18	        session::libseat::LibSeatSession,
19	    },
20	    reexports::drm::control,
21	};
22	use std::{collections::BTreeMap, io, os::fd::AsFd, rc::Rc};
23	
24	#[derive(Clone, Copy, Debug, Serialize)]
25	pub enum PreviewStage {
26	    Inactive,
27	    Busy,
28	    Admission,
29	    Prepare,
30	    Capture,
31	    Test,
32	    Submit,
33	    Restore,
34	    Cleanup,
35	}
36	#[derive(Clone, Copy, Debug, Serialize)]
37	pub struct PreviewFailure {
38	    pub stage: PreviewStage,
39	    pub errno: Option<i32>,
40	}
41	impl PreviewFailure {
42	    pub(super) fn at(stage: PreviewStage) -> Self {
43	        Self { stage, errno: None }
44	    }
45	    fn io(stage: PreviewStage, error: io::Error) -> Self {
46	        Self {
47	            stage,
48	            errno: error.raw_os_error(),
49	        }
50	    }
51	}
52	impl std::fmt::Display for PreviewFailure {
53	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
54	        write!(
55	            f,
56	            "native preview failed: {:?} ({:?})",
57	            self.stage, self.errno
58	        )
59	    }
60	}
61	impl std::error::Error for PreviewFailure {}
62	#[derive(Debug, Serialize)]
63	pub struct PreviewInfo {
64	    pub connector: u32,
65	    pub queue: frames::QueueSnapshot,
66	    pub visible_color: Option<[u8; 4]>,
67	    pub last_failure: Option<PreviewFailure>,
68	    pub rollback_completed: bool,
69	    pub rollback_cleanup_errors: u64,
70	}
71	pub(super) struct Context<'a> {
72	    pub drm: &'a DrmDevice,
73	    pub gbm: &'a GbmDevice<DrmDeviceFd>,
74	    pub renderer: &'a mut GlesRenderer,
75	    pub modes: &'a BTreeMap<u32, Vec<control::Mode>>,
76	    pub seat: Rc<SeatDevice<LibSeatSession>>,
77	    pub pool: &'a FramePool,
78	    pub ticket: Ticket,
79	}
80	struct OwnedTarget {
81	    target: Target,
82	    _seat: Rc<SeatDevice<LibSeatSession>>,
83	}
84	struct State {
85	    queue: FrameQueue<OwnedTarget, [u8; 4]>,
86	    rollback: RestoreState,
87	    fd: DrmDeviceFd,
88	    assignment: Assignment,
89	    format: Format,
90	    key: OutputKey,
91	    last_failure: Option<PreviewFailure>,
92	    rollback_completed: bool,
93	    armed: bool,
94	    // Pin broker originals until all cloned framebuffer/DRM owners have retired.
95	    _seat: Rc<SeatDevice<LibSeatSession>>,
96	}
97	pub(super) struct Output {
98	    state: Option<Box<State>>,
99	}
100	fn color(value: [u8; 4]) -> [f32; 4] {
101	    value.map(|channel| f32::from(channel) / 255.)
102	}
103	fn bytes(a: &Assignment) -> Result<u64, PreviewFailure> {
104	    let pixels = u64::from(a.mode.width) * u64::from(a.mode.height);
105	    if a.mode.width == 0
106	        || a.mode.height == 0
107	        || a.mode.width > crate::target::MAX_TEST_DIMENSION
108	        || a.mode.height > crate::target::MAX_TEST_DIMENSION
109	        || pixels > crate::target::MAX_TEST_PIXELS
110	    {
111	        return Err(PreviewFailure::at(PreviewStage::Admission));
112	    }
113	    Ok(pixels * 4)
114	}
115	impl Output {
116	    pub fn begin(
117	        ctx: &mut Context<'_>,
118	        a: Assignment,
119	        format: Format,
120	        epoch: u64,
121	        value: [u8; 4],
122	    ) -> Result<Self, PreviewFailure> {
123	        let key = OutputKey::new(ctx.ticket, a.crtc, epoch)
124	            .map_err(|_| PreviewFailure::at(PreviewStage::Admission))?;
125	        let mut queue = ctx
126	            .pool
127	            .output(key)
128	            .map_err(|_| PreviewFailure::at(PreviewStage::Admission))?;
129	        let mut request = None;
130	        let mut rollback = None;
131	        let frame = ctx
132	            .pool
133	            .prepare(bytes(&a)?, || {
134	                let (target, initial) = target_test::prepare_live(
135	                    ctx.drm,
136	                    ctx.gbm,
137	                    ctx.renderer,
138	                    ctx.modes,
139	                    &a,
140	                    format,
141	                    color(value),
142	                )
143	                .map_err(|e| PreviewFailure {
144	                    stage: PreviewStage::Prepare,
145	                    errno: e.errno,
146	                })?;
147	                let saved = RestoreState::capture(ctx.drm, &initial)
148	                    .map_err(|e| PreviewFailure::io(PreviewStage::Capture, e))?;
149	                // Both the new configuration AND rollback must pass preflight.
150	                initial
151	                    .test_only(ctx.drm.as_fd())
152	                    .map_err(|e| PreviewFailure::io(PreviewStage::Test, e))?;
153	                saved
154	                    .request()
155	                    .test_only(ctx.drm.as_fd())
156	                    .map_err(|e| PreviewFailure::io(PreviewStage::Test, e))?;
157	                request = Some(initial);
158	                rollback = Some(saved);
159	                Ok((
160	                    OwnedTarget {
161	                        target,
162	                        _seat: ctx.seat.clone(),
163	                    },
164	                    value,
165	                ))
166	            })
167	            .map_err(|e| match e {
168	                frames::PreparationError::Backend(e) => e,
169	                _ => PreviewFailure::at(PreviewStage::Admission),
170	            });
171	        let frame = match frame {
172	            Ok(frame) => frame,
173	            Err(error) => {
174	                ctx.renderer
175	                    .cleanup_texture_cache()
176	                    .map_err(|_| PreviewFailure::at(PreviewStage::Cleanup))?;
177	                return Err(error);
178	            }
179	        };
180	        let initial = request.expect("prepared initial request");
181	        let result = queue.submit(frame, |cookie, _| {
182	            match initial.submit(ctx.drm.as_fd(), cookie, true) {
183	                Ok(()) => SubmitOutcome::Accepted,
184	                // Never infer that an ioctl error proves no consumer exists.
185	                Err(error) => {
186	                    SubmitOutcome::Uncertain(PreviewFailure::io(PreviewStage::Submit, error))
187	                }
188	            }
189	        });
190	        let last_failure = match result {
191	            Ok(_) => None,
192	            Err(SubmitError::Uncertain(error)) => Some(error),
193	            Err(error) => {
194	                drop(error);
195	                ctx.renderer
196	                    .cleanup_texture_cache()
197	                    .map_err(|_| PreviewFailure::at(PreviewStage::Cleanup))?;
198	                return Err(PreviewFailure::at(PreviewStage::Admission));
199	            }
200	        };
201	        Ok(Self {
202	            state: Some(Box::new(State {
203	                queue,
204	                rollback: rollback.expect("prepared rollback"),
205	                fd: ctx.drm.device_fd().clone(),
206	                assignment: a,
207	                format,
208	                key,
209	                last_failure,
210	                rollback_completed: false,
211	                armed: true,
212	                _seat: ctx.seat.clone(),
213	            })),
214	        })
215	    }
216	    pub fn info(&self) -> PreviewInfo {
217	        let s = self.state.as_ref().expect("live output owned");
218	        PreviewInfo {
219	            connector: s.assignment.connector,
220	            queue: s.queue.snapshot(),
221	            visible_color: s.queue.visible_scene().copied(),
222	            last_failure: s.last_failure,
223	            rollback_completed: s.rollback_completed,
224	            rollback_cleanup_errors: s.rollback.cleanup_errors(),
225	        }
226	    }
227	    pub fn complete(&mut self, ticket: Ticket, event: crate::drm_events::Flip) {
228	        let s = self.state.as_mut().expect("live output owned");
229	        if s.queue.complete(ticket, event) != frames::Completion::Ignored {
230	            s.last_failure = None;
231	        }
232	    }
233	    pub fn invalidate(&mut self) {
234	        self.state
235	            .as_mut()
236	            .expect("live output owned")
237	            .queue
238	            .invalidate();
239	    }
240	    pub fn submit(&mut self, ctx: &mut Context<'_>, value: [u8; 4]) -> Result<(), PreviewFailure> {
241	        let s = self.state.as_mut().expect("live output owned");
242	        let status = s.queue.snapshot();
243	        if !status.active || status.closed || status.faulted || s.rollback_completed {
244	            return Err(PreviewFailure::at(PreviewStage::Inactive));
245	        }
246	        if status.pending_cookie.is_some() {
247	            return Err(PreviewFailure::at(PreviewStage::Busy));
248	        }
249	        let prepared = ctx
250	            .pool
251	            .prepare(bytes(&s.assignment)?, || {
252	                let (target, _) = target_test::prepare_live(
253	                    ctx.drm,
254	                    ctx.gbm,
255	                    ctx.renderer,
256	                    ctx.modes,
257	                    &s.assignment,
258	                    s.format,
259	                    color(value),
260	                )
261	                .map_err(|e| PreviewFailure {
262	                    stage: PreviewStage::Prepare,
263	                    errno: e.errno,
264	                })?;
265	                Ok((
266	                    OwnedTarget {
267	                        target,
268	                        _seat: ctx.seat.clone(),
269	                    },
270	                    value,
271	                ))
272	            })
273	            .map_err(|e| match e {
274	                frames::PreparationError::Backend(e) => e,
275	                _ => PreviewFailure::at(PreviewStage::Admission),
276	            })?;
277	        let result = s.queue.submit(prepared, |cookie, owned| {
278	            let request = match owned.target.flip_request() {
279	                Ok(r) => r,
280	                Err(e) => {
281	                    return SubmitOutcome::Rejected(PreviewFailure {
282	                        stage: PreviewStage::Prepare,
283	                        errno: e.errno,
284	                    });
285	                }
286	            };
287	            match request.submit(ctx.drm.as_fd(), cookie, false) {
288	                Ok(()) => SubmitOutcome::Accepted,
289	                Err(e) => SubmitOutcome::Uncertain(PreviewFailure::io(PreviewStage::Submit, e)),
290	            }
291	        });
292	        match result {
293	            Ok(_) => Ok(()),
294	            Err(SubmitError::Uncertain(e)) | Err(SubmitError::Rejected { error: e, .. }) => {
295	                s.last_failure = Some(e);
296	                Err(e)
297	            }
298	            Err(_) => Err(PreviewFailure::at(PreviewStage::Admission)),
299	        }
300	    }
301	    pub fn restore(&mut self) -> Result<(), PreviewFailure> {
302	        let s = self.state.as_mut().expect("live output owned");
303	        s.queue.invalidate();
304	        let rollback = &mut s.rollback;
305	        restore_consumers(&mut s.queue, s.key, &mut s.rollback_completed, || {
306	            rollback.mark_restored();
307	            rollback.request().restore(s.fd.as_fd())
308	        })?;
309	        s.rollback
310	            .finish_restored()
311	            .map_err(|e| PreviewFailure::io(PreviewStage::Cleanup, e))?;
312	        s.armed = false;
313	        Ok(())
314	    }
315	}
316	impl Drop for Output {
317	    fn drop(&mut self) {
318	        if let Some(state) = self.state.take()
319	            && state.armed
320	        {
321	            // No restore against a potentially revoked/replaced topology. Keep
322	            // resources, rollback clones, quota permits AND the broker lease.
323	            std::mem::forget(state);
324	        }
325	    }
326	}
327	
328	fn restore_consumers<R, S>(
329	    queue: &mut FrameQueue<R, S>,
330	    key: OutputKey,
331	    completed: &mut bool,
332	    restore: impl FnOnce() -> io::Result<()>,
333	) -> Result<(), PreviewFailure> {
334	    queue.invalidate();
335	    if !*completed {
336	        restore().map_err(|e| PreviewFailure::io(PreviewStage::Restore, e))?;
337	        // SAFETY: the platform closure succeeded only after a synchronous
338	        // atomic rollback replaced every plane consuming this queue's buffers.
339	        let proof = unsafe { IdleProof::after_backend_quiescence(key) };
340	        queue
341	            .release_after_disable(proof)
342	            .map_err(|_| PreviewFailure::at(PreviewStage::Restore))?;
343	        *completed = true;
344	    }
345	    Ok(())
346	}
347	#[cfg(test)]
348	mod tests {
349	    use super::*;
350	    #[test]
351	    fn failed_restore_retains_front_and_pending_until_synchronous_success() {
352	        let ticket = Ticket {
353	            device: 1,
354	            generation: 1,
355	            session_epoch: 1,
356	        };
357	        let key = OutputKey::new(ticket, 7, 1).unwrap();
358	        let pool = FramePool::default();
359	        let mut queue = pool.output(key).unwrap();
360	        let frame = pool.prepare(4, || Ok::<_, ()>((1, ()))).unwrap();
361	        let cookie = queue
362	            .submit(frame, |_, _| SubmitOutcome::<()>::Accepted)
363	            .ok()
364	            .unwrap();
365	        queue.complete(
366	            ticket,
367	            crate::drm_events::Flip {
368	                cookie: cookie.get(),
369	                crtc: 7,
370	                sequence: 1,
371	                seconds: 0,
372	                microseconds: 0,
373	            },
374	        );
375	        let next = pool.prepare(4, || Ok::<_, ()>((2, ()))).unwrap();
376	        assert!(
377	            queue
378	                .submit(next, |_, _| SubmitOutcome::<()>::Accepted)
379	                .is_ok()
380	        );
381	        let mut completed = false;
382	        assert!(
383	            restore_consumers(&mut queue, key, &mut completed, || Err(
384	                io::Error::from_raw_os_error(libc::EBUSY)
385	            ))
386	            .is_err()
387	        );
388	        assert_eq!(pool.snapshot().slots, 2);
389	        assert!(!completed);
390	        assert!(queue.visible_scene().is_none());
391	        restore_consumers(&mut queue, key, &mut completed, || {
392	            assert_eq!(pool.snapshot().slots, 2);
393	            Ok(())
394	        })
395	        .unwrap();
396	        assert_eq!(pool.snapshot().slots, 0);
397	        assert!(queue.snapshot().closed && completed);
398	        restore_consumers(&mut queue, key, &mut completed, || {
399	            panic!("rollback must not repeat after clone IDs close")
400	        })
401	        .unwrap();
402	    }
403	}
