44	            request: Request::new(),
45	            fd: Some(drm.device_fd().clone()),
46	            blobs: Vec::new(),
47	            blob_bytes: 0,
48	            framebuffers: Vec::new(),
49	            restored: false,
50	            cleanup_errors: 0,
51	        };
52	        let mut old_blobs = BTreeMap::new();
53	        let mut old_fbs = BTreeMap::new();
54	        let mut properties = BTreeMap::new();
55	        let mut count = 0;
56	        for (object, property, _) in changed.entries() {
57	            count += 1;
58	            if count > MAX_PROPERTIES {
59	                return Err(invalid("too many rollback properties"));
60	            }
61	            let kind = *objects
62	                .get(&object)
63	                .ok_or_else(|| invalid("unknown rollback object"))?;
64	            if let std::collections::btree_map::Entry::Vacant(entry) = properties.entry(object) {
65	                let values = match kind {
66	                    control::connector::Handle::FFI_TYPE => {
