144	    /// This permanently prevents RMFB cleanup of possibly restored scanout.
145	    /// The owner must retain the full backend/seat lease on restoration error.
146	    pub fn mark_restored(&mut self) {
147	        self.restored = true;
148	    }
149	    /// After synchronous rollback succeeds, release clone ownership without
150	    /// disabling restored planes. Failures retain FB IDs and the fd for retry;
151	    /// the caller must retain this entire state and its backend/seat owner.
152	    pub fn finish_restored(&mut self) -> io::Result<()> {
153	        if !self.restored {
154	            return Err(invalid("rollback not marked restored"));
155	        }
156	        let before = self.cleanup_errors;
157	        self.cleanup();
158	        if !self.framebuffers.is_empty() || !self.blobs.is_empty() || self.cleanup_errors != before
