171	        let mut get = drm_sys::drm_mode_get_blob {
172	            blob_id: original,
173	            ..Default::default()
174	        };
175	        ioctl(self.fd(), 0xac, &mut get)?;
176	        let length = get.length as usize;
177	        if length == 0
178	            || length > MAX_BLOB_BYTES
179	            || self.blob_bytes.saturating_add(length) > MAX_TOTAL_BLOB_BYTES
180	        {
