182	        }
183	        let mut bytes = vec![0u8; length];
184	        get.data = bytes.as_mut_ptr() as u64;
185	        ioctl(self.fd(), 0xac, &mut get)?;
186	        if get.length as usize != length {
187	            return Err(invalid("rollback blob changed size"));
188	        }
