190	            data: bytes.as_ptr() as u64,
191	            length: length as u32,
192	            blob_id: 0,
193	        };
194	        ioctl(self.fd(), 0xbd, &mut create)?;
195	        if create.blob_id == 0 {
196	            return Err(invalid("zero cloned blob ID"));
197	        }
198	        self.blobs.push(create.blob_id);
199	        self.blob_bytes += length;
200	        Ok(create.blob_id.into())
201	    }
202	    fn clone_framebuffer(&mut self, original: u32) -> io::Result<u64> {
203	        let mut raw = drm_sys::drm_mode_fb_cmd2 {
204	            fb_id: original,
205	            ..Default::default()
206	        };
207	        let read = ioctl(self.fd(), 0xce, &mut raw);
208	        // GETFB2 gives fresh handles, potentially repeated across planes. Install
209	        // the guard before validating anything returned by the kernel.
210	        let mut handles = Handles::new(raw.handles);
211	        handles.fd = Some(self.fd().clone());
212	        let result = (|| {
213	            read?;
214	            if raw.width == 0 || raw.height == 0 || raw.handles[0] == 0 {
215	                return Err(invalid("framebuffer unavailable for rollback"));
216	            }
217	            if raw.flags & !control::FbCmd2Flags::all().bits() != 0 {
218	                return Err(invalid("unknown framebuffer flags"));
219	            }
220	            raw.fb_id = 0;
221	            ioctl(self.fd(), 0xb8, &mut raw)?;
222	            let fb = handle::<control::framebuffer::Handle>(raw.fb_id)?;
223	            self.framebuffers.push(fb);
224	            Ok(u64::from(raw.fb_id))
