226	        let close = handles.close(|id| self.fd().close_buffer(handle(id)?));
227	        if close > 0 {
228	            self.cleanup_errors = self.cleanup_errors.saturating_add(close);
229	            return Err(io::Error::other("failed to close rollback GEM handle"));
230	        }
231	        result
232	    }
233	}
234	impl RestoreState {
235	    /// Release userspace leases. After restoration CLOSEFB preserves scanout;
236	    /// unsupported/error kernels retain the file description rather than RMFB.
237	    /// Returns the cumulative count of failed cleanup operations.
238	    pub fn cleanup(&mut self) -> u64 {
239	        let mut retained_blobs = Vec::new();
240	        for blob in self.blobs.drain(..) {
241	            if self
242	                .fd
243	                .as_ref()
244	                .unwrap()
245	                .destroy_property_blob(blob.into())
246	                .is_err()
247	            {
248	                self.cleanup_errors = self.cleanup_errors.saturating_add(1);
249	                retained_blobs.push(blob);
250	            }
251	        }
252	        self.blobs = retained_blobs;
253	        let mut retained = Vec::new();
254	        for fb in self.framebuffers.drain(..) {
255	            let result = if self.restored {
256	                let mut close = drm_sys::drm_mode_closefb {
257	                    fb_id: fb.into(),
258	                    pad: 0,
259	                };
260	                ioctl(self.fd.as_ref().unwrap(), 0xd0, &mut close)
261	            } else {
262	                self.fd.as_ref().unwrap().destroy_framebuffer(fb)
263	            };
264	            if result.is_err() {
265	                self.cleanup_errors = self.cleanup_errors.saturating_add(1);
266	                retained.push(fb);
267	            }
268	        }
269	        self.framebuffers = retained;
270	        self.cleanup_errors
271	    }
272	}
273	impl Drop for RestoreState {
274	    fn drop(&mut self) {
275	        self.cleanup();
276	    }
277	}
278	fn handle<H: From<control::RawResourceHandle>>(value: u32) -> io::Result<H> {
279	    std::num::NonZeroU32::new(value)
280	        .map(H::from)
281	        .ok_or_else(|| invalid("zero resource handle"))
282	}
283	fn insert_object<H: ResourceHandle>(objects: &mut BTreeMap<u32, u32>, handle: H) -> io::Result<()> {
284	    let raw: control::RawResourceHandle = handle.into();
285	    if objects.len() == MAX_OBJECTS || objects.insert(raw.get(), H::FFI_TYPE).is_some() {
286	        return Err(invalid("duplicate or excessive KMS objects"));
287	    }
288	    Ok(())
289	}
290	fn invalid(message: &'static str) -> io::Error {
291	    io::Error::new(io::ErrorKind::InvalidData, message)
292	}
293	// This adapter changes only this qualified property set. New driver-specific
294	// properties need an explicit lifetime/side-effect review before adding them.
295	fn supported(kind: u32, name: &[u8]) -> bool {
296	    match kind {
297	        control::connector::Handle::FFI_TYPE => name == b"CRTC_ID",
298	        control::crtc::Handle::FFI_TYPE => matches!(name, b"ACTIVE" | b"MODE_ID"),
299	        control::plane::Handle::FFI_TYPE => matches!(
300	            name,
301	            b"FB_ID"
302	                | b"CRTC_ID"
303	                | b"SRC_X"
304	                | b"SRC_Y"
305	                | b"SRC_W"
306	                | b"SRC_H"
307	                | b"CRTC_X"
308	                | b"CRTC_Y"
309	                | b"CRTC_W"
310	                | b"CRTC_H"
311	                | b"rotation"
312	                | b"alpha"
313	        ),
314	        _ => false,
315	    }
316	}
317	fn transient(name: &[u8]) -> bool {
318	    name.windows(5).any(|part| part == b"FENCE")
319	        || name.starts_with(b"WRITEBACK_")
320	        || name == b"FB_DAMAGE_CLIPS"
321	}
322	fn ioctl<T>(fd: &DrmDeviceFd, number: u8, data: &mut T) -> io::Result<()> {
323	    // SAFETY: private callers select matching pinned repr(C) DRM structures;
324	    // all pointer-bearing buffers remain live for this synchronous ioctl.
325	    let result = unsafe {
326	        libc::ioctl(
327	            fd.as_fd().as_raw_fd(),
328	            opcode::read_write::<T>(b'd', number) as libc::c_ulong,
329	            data as *mut T,
330	        )
331	    };
332	    if result < 0 {
333	        Err(io::Error::last_os_error())
334	    } else {
335	        Ok(())
336	    }
337	}
338	struct Handles {
339	    remaining: BTreeSet<u32>,
340	    fd: Option<DrmDeviceFd>,
341	}
342	impl Handles {
343	    fn new(handles: [u32; 4]) -> Self {
344	        Self {
345	            remaining: handles.into_iter().filter(|&id| id != 0).collect(),
346	            fd: None,
347	        }
348	    }
349	    fn close(&mut self, mut close: impl FnMut(u32) -> io::Result<()>) -> u64 {
350	        let mut errors = 0;
351	        while let Some(id) = self.remaining.pop_first() {
352	            if close(id).is_err() {
353	                errors += 1;
354	            }
355	        }
356	        errors
357	    }
358	}
359	impl Drop for Handles {
360	    fn drop(&mut self) {
361	        if let Some(fd) = self.fd.take() {
362	            self.close(|id| fd.close_buffer(handle(id)?));
363	        }
364	    }
365	}
366	#[cfg(test)]
367	mod tests {
368	    use super::*;
369	    #[test]
370	    fn distinct_getfb_handles_closed_once_even_when_close_fails() {
371	        let mut handles = Handles::new([4, 4, 0, 7]);
372	        let mut seen = Vec::new();
373	        assert_eq!(
374	            handles.close(|id| {
375	                seen.push(id);
376	                Err(io::Error::other("fixture"))
377	            }),
378	            2
379	        );
380	        assert_eq!(seen, [4, 7]);
381	        assert_eq!(handles.close(|_| panic!("closed twice")), 0);
382	    }
383	    #[test]
384	    fn unknown_and_wrong_object_properties_are_rejected() {
385	        assert!(supported(control::plane::Handle::FFI_TYPE, b"FB_ID"));
386	        assert!(supported(control::crtc::Handle::FFI_TYPE, b"MODE_ID"));
387	        assert!(!supported(control::connector::Handle::FFI_TYPE, b"FB_ID"));
388	        assert!(!supported(
389	            control::plane::Handle::FFI_TYPE,
390	            b"vendor_magic"
391	        ));
392	    }
393	    #[test]
394	    fn transient_values_are_rejected() {
395	        for name in [
396	            b"IN_FENCE_FD".as_slice(),
397	            b"OUT_FENCE_PTR",
398	            b"WRITEBACK_FB_ID",
399	            b"FB_DAMAGE_CLIPS",
400	        ] {
401	            assert!(transient(name));
402	        }
403	        for name in [b"MODE_ID".as_slice(), b"FB_ID", b"CRTC_ID", b"ACTIVE"] {
404	            assert!(!transient(name));
405	        }
406	    }
407	}
