fn stop(&mut self) {
    self.model.stop();
    if let Some(input) = &mut self.input {
        input.suspend();
    }
    self.input_token.take();
    self.input.take();
    let devices: Vec<_> = self.gpus.keys().copied().collect();
    for id in devices {
        self.retire(id);
    }
    self.paths.clear();
}
fn pause(&mut self) -> Vec<NativeEvent> {
    match self.model.pause() {
        Ok(false) => vec![],
        Ok(true) => {
            if let Some(input) = &mut self.input {
                input.suspend();
            }
            for gpu in self.gpus.values_mut() {
                if let Some(mut output) = gpu.output.take() {
                    output.invalidate();
                    // Seat revocation is not a quiescence proof. Do not
                    // restore an old topology after its session epoch ends.
                    self.output_cleanup_failures =
                        self.output_cleanup_failures.saturating_add(1);
                }
                gpu.drm.pause();
            }
            vec![NativeEvent::SessionActive(false)]
        }
        Err(_) => {
            self.stop();
            vec![
                Self::failure(None, Stage::Lifecycle),
                NativeEvent::SessionActive(false),
            ]
        }
    }
}
