// active-device KMS restore on Changed/Removed/stop; no surfaces exist yet.
fn retire_paused<T>(resource: Option<T>, pause: impl FnOnce(&mut T)) {
    if let Some(mut resource) = resource {
        pause(&mut resource);
    }
