22	    let mut result = BTreeMap::new();
23	    for route in routes {
24	        if route.id == 0
25	            || route.crtc.is_some_and(|id| !known.contains(&id))
26	            || result.insert(route.id, route.crtc).is_some()
27	        {
28	            return Err(invalid());
