33	pub fn reconcile(
34	    assignments: &[Assignment],
35	    connectors: &[Route],
36	    planes: &[Route],
37	    crtcs: &[u32],
38	) -> Result<Reconciled, TestFailure> {
39	    if assignments.len() > super::MAX_TEST_TARGETS
40	        || connectors.len() > MAX_CONNECTORS
41	        || planes.len() > 256
42	        || crtcs.len() > MAX_CRTCS
43	    {
44	        return Err(TestFailure::at(TestStage::Budget));
45	    }
46	    let known: BTreeSet<_> = crtcs.iter().copied().collect();
47	    if known.len() != crtcs.len() || known.contains(&0) {
48	        return Err(invalid());
49	    }
50	    let before = map(connectors, &known)?;
51	    let plane_routes = map(planes, &known)?;
52	    let mut after = before.clone();
53	    let mut tested = BTreeSet::new();
54	    let mut selected = BTreeSet::new();
55	    let mut planned = BTreeSet::new();
56	    let mut sources = BTreeSet::new();
57	    for a in assignments {
58	        if !before.contains_key(&a.connector)
59	            || !plane_routes.contains_key(&a.primary_plane)
60	            || !known.contains(&a.crtc)
61	            || !tested.insert(a.crtc)
62	            || !selected.insert(a.primary_plane)
63	            || !planned.insert(a.connector)
64	        {
65	            return Err(invalid());
66	        }
67	        if let Some(source) = before[&a.connector] {
68	            sources.insert(source);
69	        }
70	        if let Some(source) = plane_routes[&a.primary_plane] {
71	            sources.insert(source);
72	        }
73	        after.insert(a.connector, Some(a.crtc));
74	    }
75	    for (connector, crtc) in &mut after {
76	        if !planned.contains(connector) && crtc.is_some_and(|id| tested.contains(&id)) {
77	            *crtc = None;
78	        }
79	    }
80	    let mut disabled = BTreeSet::new();
81	    for source in sources.difference(&tested) {
82	        let remaining = after.values().any(|crtc| *crtc == Some(*source));
83	        let primary_stolen = assignments
84	            .iter()
85	            .any(|a| plane_routes[&a.primary_plane] == Some(*source));
86	        if remaining && primary_stolen {
87	            return Err(TestFailure::at(TestStage::TopologyConflict));
88	        }
89	        if !remaining {
90	            disabled.insert(*source);
91	        }
92	    }
93	    let affected: BTreeSet<_> = tested.union(&disabled).copied().collect();
94	    let cleared = plane_routes
95	        .iter()
96	        .filter(|(id, crtc)| {
97	            !selected.contains(id) && crtc.is_some_and(|id| affected.contains(&id))
98	        })
99	        .map(|(id, _)| *id)
100	        .collect();
101	    Ok(Reconciled {
102	        connectors: after,
103	        disabled_crtcs: disabled,
104	        cleared_planes: cleared,
